text:
目标： 10 分钟内跑出第一个窗口 ，并清楚接下来该看哪一章。按下面的步骤走即可。  第 0 步：准备（纯头文件，零构建配置） - 把 ZufyUI.h 、 ZufyUIWidgets.h 、 ZDataViewer.h 、 ZufyUICharts.h 、 ZufyUIWindowTool.h 、 ZufyUIDragDrop.h 所在目录加入 包含路径 即可； 不需要编译任何 .cpp ，也不依赖第三方库。
- 依赖的系统库全部由库内 #pragma comment(lib, ...) 自动链接（完整清单见「环境要求」）。
- GUI 程序入口用 wWinMain + /SUBSYSTEM:WINDOWS 。
- 环境对 BOM / 中文源码不友好时，先运行 纯 ASCII 导出 ，用 dist/ascii 里的头文件。
- ⚠ 入口易错 ：若坚持写 int main() ，必须把子系统设成 /SUBSYSTEM:CONSOLE ，或加 #pragma comment(linker, "/SUBSYSTEM:WINDOWS /ENTRY:mainCRTStartup") ，否则链接器找不到入口。  第 1 步：最小窗口 + 一个按钮 + 一个开关  cpp 复制 #include "ZufyUIWidgets.h" using namespace ZufyUI ; int WINAPI wWinMain ( HINSTANCE , HINSTANCE , LPWSTR , int ) { Window win ; if ( ! win . Create ( 1000 , 700 , L "ZufyUI Demo" )) return 1 ; auto root = win . GetRootColumnBox (); root -> SetSpacing ( 10 ); auto row = std :: make_shared < RowBox > (); row -> SetSpacing ( 10 ); auto btn = std :: make_shared < Button > ( L "点我" ); btn -> Connect ( btn -> Clicked , []() { MessageBoxW ( nullptr , L "Hello ZufyUI!" , L "提示" , MB_OK ); }); auto toggle = std :: make_shared < ToggleSwitch > ( false ); auto state = std :: make_shared < Label > ( L "开关：关" ); toggle -> Connect ( toggle -> Toggled , [ state ]( bool on ) { state -> SetText ( on ? L "开关：开" : L "开关：关" ); }); row -> AddChild ( btn ); row -> AddChild ( toggle ); row -> AddChild ( state ); root -> AddChild ( row ); win . Run (); return 0 ; } #include "ZufyUIWidgets.h"
using namespace ZufyUI;

int WINAPI wWinMain(HINSTANCE, HINSTANCE, LPWSTR, int) {
    Window win;
    if (!win.Create(1000, 700, L"ZufyUI Demo"))
        return 1;

    auto root = win.GetRootColumnBox();
    root->SetSpacing(10);

    auto row = std::make_shared<RowBox>();
    row->SetSpacing(10);

    auto btn = std::make_shared<Button>(L"点我");
    btn->Connect(btn->Clicked, []() {
        MessageBoxW(nullptr, L"Hello ZufyUI!", L"提示", MB_OK);
    });

    auto toggle = std::make_shared<ToggleSwitch>(false);
    auto state = std::make_shared<Label>(L"开关：关");
    toggle->Connect(toggle->Toggled, [state](bool on) {
        state->SetText(on ? L"开关：开" : L"开关：关");
    });

    row->AddChild(btn);
    row->AddChild(toggle);
    row->AddChild(state);
    root->AddChild(row);

    win.Run();
    return 0;
}  要点（每一步都在做什么）：  Window::Create 会创建窗口、初始化 Direct2D、应用背景并生成一个默认的根 ColumnBox （margin 20、spacing 10）； 控件用 std::make_shared<T>() 创建， AddChild 挂到布局上； 父容器用 shared_ptr 拥有子元素 ； 用 Connect(信号, 槽) 绑定事件，连接会随接收者（控件/窗口）析构自动断开；需要弱引用保活时用 ConnectWeak ； 最后 win.Run() 进入消息循环；所有窗口/控件都在 同一 UI 线程 创建与操作。 ⚠ 单位 ：坐标与尺寸都是 DIP （不是物理像素），框架自动做 DPI 吸附，你不必自己换算。  运行效果（就是上面这段代码）：    第 2 / 3 步：换个背景、换个标题栏  第 2 步：换个背景。 只有三个背景层可选—— 无 / 亚克力 / 云母 ，背景层之上再叠一个带 Alpha 的颜色：  cpp 复制 win . SetBackdrop ( Backdrop :: Mica , 0x00000000 ); // 云母 + 全透明叠加色 win.SetBackdrop(Backdrop::Mica, 0x00000000);   // 云母 + 全透明叠加色    第 3 步：自定义标题栏。 换个标题栏（顺带换成云母背景，标题栏更明显）：  cpp 复制 #include "ZufyUIWindowTool.h" // DefaultTitleBar 在这里 auto bar = std :: make_shared < DefaultTitleBar > (); win . SetCustomTitleBar ( bar ); win . SetBackdrop ( Backdrop :: Mica , 0x00000000 ); // 顺带换成云母 #include "ZufyUIWindowTool.h"   // DefaultTitleBar 在这里

auto bar = std::make_shared<DefaultTitleBar>();
win.SetCustomTitleBar(bar);
win.SetBackdrop(Backdrop::Mica, 0x00000000);   // 顺带换成云母    第 4 步：接下来看什么 - 布局与控件总览： API 参考 · 布局系统 / 基础控件 - 数据界面（列表 / 表格 / 树）：API 参考「数据视图」章
- 画图表：API 参考「图表」章（ BarChart / LineChart / PieChart ）
- 窗口周边（标题栏 / 托盘 / 系统对话框）：API 参考「窗口周边」章
- 无障碍与调试/自动化：API 参考「无障碍与调试通道」章  务必记住的三件事 1. DIP ：所有尺寸/坐标都是 DIP，不用管 DPI。
2. shared_ptr 即所有权 ：控件用 make_shared 拥有、 AddChild 挂父；丢掉唯一的 shared_ptr 就等于销毁。
3. 入口/子系统 ： wWinMain + /SUBSYSTEM:WINDOWS （或按上面的“入口易错”处理）。
